function findCircleNum(isConnected) {
  const n = isConnected.length;
  const parent = Array.from({ length: n }, (_, i) => i);   // every city leads its own group
  const find = (x) => {
    while (parent[x] !== x) {
      parent[x] = parent[parent[x]];      // path halving: point closer to the leader as we go
      x = parent[x];
    }
    return x;
  };
  let provinces = n;
  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j < n; j++) {     // each road once (the matrix is symmetric)
      if (isConnected[i][j] !== 1) continue;
      const a = find(i), b = find(j);
      if (a !== b) {
        parent[a] = b;                    // merge the two groups...
        provinces--;                      // ...so there is one province fewer
      }
    }
  }
  return provinces;
}

def find_circle_num(is_connected):
    n = len(is_connected)
    parent = list(range(n))               # every city leads its own group

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]] # path halving: point closer to the leader as we go
            x = parent[x]
        return x

    provinces = n
    for i in range(n):
        for j in range(i + 1, n):         # each road once (the matrix is symmetric)
            if is_connected[i][j] != 1:
                continue
            a, b = find(i), find(j)
            if a != b:
                parent[a] = b             # merge the two groups...
                provinces -= 1            # ...so there is one province fewer
    return provinces

